<?php $section=\Chengyu\Core\Input::choice($_GET['section']??'cases',['cases','refunds','payouts','membership']);$factorRequired=$a->secondFactor->status((int)$me['id'])['enabled']; ?>
<section class="page-hero"><div><span class="eyebrow">CARE / VERIFIED RESOLUTION</span><h1><?= e($title) ?></h1><p><?= t('Approvals require your password and enabled second factor. Uncertain external results never release money.') ?></p></div><?= icon('shield') ?></section><nav class="row wrap section"><?php foreach(['cases'=>'Service requests','refunds'=>'Refund queue','payouts'=>'Payout queue','membership'=>'Membership reconciliation'] as $key=>$label): ?><a class="btn secondary small" href="<?= e(au('service',['section'=>$key])) ?>"><?= t($label) ?></a><?php endforeach ?></nav>
<?php if($section==='cases'): $rows=$a->db->all('SELECT * FROM cy_aftersales ORDER BY id DESC LIMIT 60');foreach($rows as $row): ?><section class="panel glass commerce-panel section"><div class="row between wrap"><h2>#<?= (int)$row['id'] ?> &middot; <?= t($row['kind']) ?></h2><span class="pill"><?= t($row['state']) ?></span></div><p><?= t('Order') ?> #<?= (int)$row['order_id'] ?> / <?= t('Account') ?> #<?= (int)$row['user_id'] ?></p><p><?= nl2br(e($row['reason'])) ?></p><?php if($row['evidence_id']): ?><a class="text-link" href="<?= e(media_url((int)$row['evidence_id'])) ?>"><?= t('Evidence') ?></a><?php endif ?><?php foreach(['return_tracking','replacement_tracking'] as $track): if($row[$track]): ?><p><?= t($track) ?>: <?= e($a->crypto->open($row[$track])) ?></p><?php endif;endforeach ?><?php if($row['note']): ?><p class="commerce-note"><?= nl2br(e($row['note'])) ?></p><?php endif ?>
<?php $options=[];if($row['state']==='requested'){$options=['approve'=>'Approve','reject'=>'Reject'];}elseif($row['state']==='awaiting_return'){$options=['reject'=>'Reject before return'];}elseif($row['state']==='return_in_transit'){$options=['received'=>'Confirm returned goods received'];}elseif($row['state']==='returned'&&$row['kind']==='exchange'){$options=['replace'=>'Ship same-SKU replacement'];}if($options): ?><details><summary><?= t('Review this request') ?></summary><?= form_start('admin_aftersale_review','','',false).hidden('id',$row['id']).hidden('revision',$row['revision']) ?><?php select_field('operation','Operation',$options,array_key_first($options));field('note','Customer-visible instructions and review note','','textarea',['required'=>'required','maxlength'=>'2000']);if($row['state']==='return_in_transit'){check_field('sellable','Returned goods are inspected and fit to restock.',false);}if($row['state']==='returned'){field('tracking','Replacement carrier and tracking number','','text',['required'=>'required','maxlength'=>'1000']);}partial('factor_proof',['factorRequired'=>$factorRequired]);button('Submit reviewed operation','secondary','shield'); ?></form></details><?php endif ?></section><?php endforeach ?>
<?php elseif($section==='refunds'||$section==='payouts'): $refund=$section==='refunds';$table=$refund?'cy_refunds':'cy_payouts';$rows=$a->db->all('SELECT * FROM '.$table.' ORDER BY id DESC LIMIT 80'); ?>
<?php if(!$refund): ?><section class="panel glass commerce-panel"><h2><?= t('Queue a PayPal payout') ?></h2><p class="hint"><?= t('Only approved merchant accounts with PayPal Payouts access can send. The original withdrawal receiver must be an email address; currency conversion and receiver substitution are blocked.') ?></p><?= form_start('admin_payout_queue','','',false) ?><?php field('withdrawal_id','Pending withdrawal ID','','number',['min'=>'1','required'=>'required']);partial('factor_proof',['factorRequired'=>$factorRequired]);button('Approve and queue payout','secondary','shield'); ?></form></section><?php endif ?>
<?php foreach($rows as $row): ?><section class="panel glass commerce-panel section"><div class="row between wrap"><h2>#<?= (int)$row['id'] ?> / <?= e($refund?$row['refund_no']:$row['batch_key']) ?></h2><span class="pill"><?= t($row['status']) ?></span></div><p><?= t($refund?'Order':'Withdrawal') ?> #<?= (int)$row[$refund?'order_id':'withdrawal_id'] ?> &middot; <?= e(($refund?(string)$s->get('store_currency'):$row['currency']).' '.money((int)$row['amount'])) ?></p><?php if($row['last_error']): ?><p class="alert warning"><?= t($row['last_error']) ?></p><?php endif ?><?php if(!in_array($row['status'],['succeeded','paid','failed'],true)): ?><details><summary><?= t('Run or verify this task') ?></summary><?= form_start($refund?'admin_refund_run':'admin_payout_run','','',false).hidden('id',$row['id']) ?><?php partial('factor_proof',['factorRequired'=>$factorRequired]);button('Run or verify','secondary','refresh'); ?></form></details><?php endif ?></section><?php endforeach ?>
<?php else: ?><div class="commerce-grid"><section class="panel glass commerce-panel"><h2><?= t('Import a verified historical membership lot') ?></h2><p><?= t('Use the original paid receipt and exact entitlement dates. The system caps credit at the amount actually paid; manual or free grants cannot create paid value.') ?></p><?= form_start('admin_lot_import','','',false) ?><?php field('order_id','Original paid membership order ID','','number',['min'=>'1','required'=>'required']);field('starts_at','Verified start Unix timestamp','','number',['min'=>'1','required'=>'required']);field('until_at','Verified end Unix timestamp','','number',['min'=>'1','required'=>'required']);partial('factor_proof',['factorRequired'=>$factorRequired]);button('Import verified lot','secondary','shield'); ?></form></section><section class="panel glass commerce-panel"><h2><?= t('Roll back an eligible upgrade') ?></h2><p><?= t('Only unchanged upgrade entitlements can roll back. Original source dates return and only the additional amount paid is refunded.') ?></p><?= form_start('admin_upgrade_refund','','',false) ?><?php field('order_id','Upgrade order ID','','number',['min'=>'1','required'=>'required']);partial('factor_proof',['factorRequired'=>$factorRequired]);button('Approve upgrade rollback','secondary','shield'); ?></form></section></div><?php endif ?>